type Props = {
  selectedKabupaten?: KabupatenName | null;
  selectedZona?: ZonaName | null;
  selectedSubWpp?: SubWppName | null;
  onKabupatenSelect?: (kabupaten: KabupatenName) => void;
  onZonaSelect?: (zona: ZonaName) => void;
  onSubWppSelect?: (subWpp: SubWppName) => void;
  interactiveLayer?: "kabupaten" | "zonasi" | "sub-wpp";
  className?: string;
};

export default function StackedMalukuUtaraSelector({
  selectedKabupaten = null,
  selectedZona = null,
  selectedSubWpp = null,
  onKabupatenSelect,
  onZonaSelect,
  onSubWppSelect,
  interactiveLayer = "kabupaten",
  className = "",
}: Props) {
  function handleKeyDown(
    event: KeyboardEvent<SVGPathElement>,
    callback: () => void,
  ) {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      callback();
    }
  }

  return (
    <div
      className={`relative aspect-[1200/1000] w-full ${className}`}
      role="group"
      aria-label="Peta selector Maluku Utara"
    >
      {/* Bottom layer: simplified_sub-wpp */}
      <svg
        viewBox="0 0 1200 1000"
        preserveAspectRatio="xMidYMid meet"
        className={[
          "absolute inset-0 z-10 h-full w-full text-white transition-opacity",
          interactiveLayer === "sub-wpp"
            ? "pointer-events-auto opacity-100"
            : "pointer-events-none opacity-0",
        ].join(" ")}
        aria-label="Sub-WPP"
      >
        {SUB_WPP.map((region) => {
          const selected = selectedSubWpp === region.name;
          const selectable =
            interactiveLayer === "sub-wpp" && Boolean(onSubWppSelect);

          return (
            <path
              key={region.id}
              d={region.path}
              role={selectable ? "button" : undefined}
              tabIndex={selectable ? 0 : -1}
              aria-label={region.label}
              aria-pressed={selectable ? selected : undefined}
              onClick={
                selectable
                  ? () => onSubWppSelect?.(region.name)
                  : undefined
              }
              onKeyDown={
                selectable
                  ? (event) =>
                      handleKeyDown(event, () =>
                        onSubWppSelect?.(region.name),
                      )
                  : undefined
              }
              className={[
                "stroke-current stroke-[2] [vector-effect:non-scaling-stroke]",
                "transition-colors",
                selected
                  ? "fill-amber-300 hover:fill-amber-200"
                  : "fill-sky-500 hover:fill-sky-400",
                selectable ? "cursor-pointer" : "",
              ].join(" ")}
            >
              <title>{region.label}</title>
            </path>
          );
        })}
      </svg>

      {/* Middle layer: all dissolved zonasi_* */}
      <svg
        viewBox="0 0 1200 1000"
        preserveAspectRatio="xMidYMid meet"
        className={[
          "absolute inset-0 z-20 h-full w-full text-white transition-opacity",
          interactiveLayer === "zonasi"
            ? "pointer-events-auto opacity-100"
            : "pointer-events-none opacity-0",
        ].join(" ")}
        aria-label="Kawasan zonasi konservasi"
      >
        {ZONASI.map((region) => {
          const selected = selectedZona === region.name;
          const selectable =
            interactiveLayer === "zonasi" && Boolean(onZonaSelect);

          return (
            <path
              key={region.id}
              d={region.path}
              role={selectable ? "button" : undefined}
              tabIndex={selectable ? 0 : -1}
              aria-label={region.label}
              aria-pressed={selectable ? selected : undefined}
              onClick={
                selectable
                  ? () => onZonaSelect?.(region.name)
                  : undefined
              }
              onKeyDown={
                selectable
                  ? (event) =>
                      handleKeyDown(event, () =>
                        onZonaSelect?.(region.name),
                      )
                  : undefined
              }
              className={[
                "stroke-current stroke-[1.5] [vector-effect:non-scaling-stroke]",
                "transition-colors",
                selected
                  ? "fill-amber-300 hover:fill-amber-200"
                  : "fill-emerald-500 hover:fill-emerald-400",
                selectable ? "cursor-pointer" : "",
              ].join(" ")}
            >
              <title>{region.label}</title>
            </path>
          );
        })}
      </svg>

      {/* Top layer: trimmed_simplified_malut_kab */}
      <svg
        viewBox="0 0 1200 1000"
        preserveAspectRatio="xMidYMid meet"
        className={[
          "absolute inset-0 z-30 h-full w-full text-white transition-opacity",
          interactiveLayer === "kabupaten"
            ? "pointer-events-auto opacity-100"
            : "pointer-events-none opacity-50",
        ].join(" ")}
        aria-label="Kabupaten dan kota Maluku Utara"
      >
        {KABUPATEN.map((region) => {
          const selected = selectedKabupaten === region.name;
          const selectable =
            interactiveLayer === "kabupaten" &&
            Boolean(onKabupatenSelect);

          return (
            <path
              key={region.id}
              d={region.path}
              role={selectable ? "button" : undefined}
              tabIndex={selectable ? 0 : -1}
              aria-label={region.label}
              aria-pressed={selectable ? selected : undefined}
              onClick={
                selectable
                  ? () => onKabupatenSelect?.(region.name)
                  : undefined
              }
              onKeyDown={
                selectable
                  ? (event) =>
                      handleKeyDown(event, () =>
                        onKabupatenSelect?.(region.name),
                      )
                  : undefined
              }
              className={[
                "stroke-current stroke-[2] [vector-effect:non-scaling-stroke]",
                "transition-colors focus:outline-none",
                selected
                  ? "fill-amber-300 hover:fill-amber-200"
                  : "fill-stone-400 hover:fill-stone-300",
                selectable ? "cursor-pointer" : "",
              ].join(" ")}
            >
              <title>{region.label}</title>
            </path>
          );
        })}
      </svg>
    </div>
  );
}

export { KABUPATEN, ZONASI, SUB_WPP };
